"use client"

import { useEffect, useRef } from "react"
import { helixItems } from "@/lib/gallery-data"

/**
 * A 3D "double helix" carousel of floating image cards, inspired by the
 * Anthropic hero. Two intertwined strands of cards spiral around a vertical
 * axis in a tall column that also drifts upward, while the whole world slowly
 * rotates. A requestAnimationFrame loop recomputes every card each frame and
 * derives depth-of-field (blur / brightness / opacity / scale) from world
 * depth. Stacking is handled by real CSS 3D sorting (preserve-3d), not manual
 * z-index, which keeps the overlaps physically correct.
 *
 * Technique: CSS 3D transforms + JS. No canvas, no WebGL.
 */

const RADIUS = 480 // cylinder radius (px)
const PITCH = 58 // vertical spacing between consecutive cards (px)
const ANG_STEP = 0.5 // radians between consecutive cards
const SPIN_SPEED = 0.00026 // helix rotation (rad/ms)
const DRIFT_SPEED = 0.032 // vertical climb (px/ms)
const WORLD_SPEED = 0.0016 // whole-world Y rotation (deg/ms)

export function HelixGallery() {
  const sceneRef = useRef<HTMLDivElement>(null)
  const stageRef = useRef<HTMLDivElement>(null)
  const cardsRef = useRef<HTMLDivElement[]>([])

  const angleRef = useRef(0) // scrubbable helix rotation (rad)
  const driftRef = useRef(0) // scrubbable vertical drift (px)
  const worldRef = useRef(0) // whole-world spin (deg)
  const spinVelRef = useRef(SPIN_SPEED)
  const draggingRef = useRef(false)
  const lastXRef = useRef(0)
  const reducedMotionRef = useRef(false)

  const items = helixItems
  const count = items.length

  useEffect(() => {
    const cards = cardsRef.current
    const stage = stageRef.current
    if (!cards.length || !stage) return

    const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
    reducedMotionRef.current = mq.matches
    const onMq = () => (reducedMotionRef.current = mq.matches)
    mq.addEventListener("change", onMq)

    // Responsive scale: shrink the helix on narrow screens.
    const scaleForWidth = () => {
      const w = window.innerWidth
      if (w < 640) return 0.55
      if (w < 1024) return 0.78
      return 1
    }

    const span = count * PITCH
    let raf = 0
    let last = performance.now()

    const render = (now: number) => {
      const dt = Math.min(now - last, 64)
      last = now

      if (!draggingRef.current) {
        if (reducedMotionRef.current) {
          spinVelRef.current = 0
        } else {
          // Ease back toward the gentle idle spin after a fling.
          spinVelRef.current += (SPIN_SPEED - spinVelRef.current) * 0.02
        }
      }

      angleRef.current += spinVelRef.current * dt
      if (!reducedMotionRef.current) {
        driftRef.current += DRIFT_SPEED * dt
        worldRef.current += WORLD_SPEED * dt
      }

      const rScale = scaleForWidth()
      const radius = RADIUS * rScale
      const pitch = PITCH * rScale
      const vSpan = span * rScale

      stage.style.transform = `translate(-50%, -50%) rotateX(-4deg) rotateY(${worldRef.current}deg)`

      for (let i = 0; i < count; i++) {
        const card = cards[i]
        if (!card) continue

        // Two intertwined strands: offset every other card half a turn.
        const strand = i % 2 ? Math.PI : 0
        const ang = i * ANG_STEP + angleRef.current + strand

        // Elliptical ring: stretch X so cards reach the frame edges.
        const x = Math.cos(ang) * radius * 1.45
        const z = Math.sin(ang) * radius
        // Vertical position climbs and wraps for an endless column.
        const y = (((i * pitch + driftRef.current) % vSpan) + vSpan) % vSpan - vSpan / 2

        const front = (z + radius) / (2 * radius) // 0 (back) -> 1 (front)
        const scale = (0.58 + front * 0.34) * rScale
        const blur = 0 //(1 - front) * 3.4
        const brightness = 1 //0.42 + front * 0.62
        const opacity = 1 //0.24 + front * 0.76

        card.style.transform = `translate3d(${x}px, ${y}px, ${z}px) rotateY(${90 - ang * 57.3}deg) scale(${scale})`
        card.style.filter = `blur(${blur.toFixed(2)}px) brightness(${brightness.toFixed(2)})`
        card.style.opacity = opacity.toFixed(3)
      }

      raf = requestAnimationFrame(render)
    }

    raf = requestAnimationFrame(render)

    return () => {
      cancelAnimationFrame(raf)
      mq.removeEventListener("change", onMq)
    }
  }, [count])

  // Pointer drag to scrub the rotation.
  useEffect(() => {
    const scene = sceneRef.current
    if (!scene) return

    const onDown = (e: PointerEvent) => {
      draggingRef.current = true
      lastXRef.current = e.clientX
      scene.setPointerCapture(e.pointerId)
    }
    const onMove = (e: PointerEvent) => {
      if (!draggingRef.current) return
      const dx = e.clientX - lastXRef.current
      lastXRef.current = e.clientX
      angleRef.current += dx * 0.004
      spinVelRef.current = dx * 0.0003 // fling momentum
    }
    const onUp = (e: PointerEvent) => {
      draggingRef.current = false
      try {
        scene.releasePointerCapture(e.pointerId)
      } catch {}
    }

    scene.addEventListener("pointerdown", onDown)
    scene.addEventListener("pointermove", onMove)
    scene.addEventListener("pointerup", onUp)
    scene.addEventListener("pointercancel", onUp)
    scene.addEventListener("pointerleave", onUp)

    return () => {
      scene.removeEventListener("pointerdown", onDown)
      scene.removeEventListener("pointermove", onMove)
      scene.removeEventListener("pointerup", onUp)
      scene.removeEventListener("pointercancel", onUp)
      scene.removeEventListener("pointerleave", onUp)
    }
  }, [])

  return (
    <div
      ref={sceneRef}
      className="helix-scene helix-fade-in absolute inset-0 cursor-grab touch-none select-none active:cursor-grabbing"
      aria-hidden="true"
    >
      <div ref={stageRef} className="helix-stage">
        {items.map((item, i) => (
          <div
            key={i}
            ref={(el) => {
              if (el) cardsRef.current[i] = el
            }}
            className="helix-card"
          >
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={item.src || "/placeholder.svg"} alt="" className="h-full w-full object-cover" draggable={false} />
            <span className="helix-card-sheen" aria-hidden="true" />
          </div>
        ))}
      </div>
    </div>
  )
}
